use super::*;
fn observe<T>(work:impl FnOnce()->T)->(T,usize,usize){crate::registry::tests::observe_ownership(work)}
#[derive(semio_framework_value::RetireOwned)]
struct Sources{source:Tree,result:Option<Tree>}
#[test]
fn original_tree_projection_retains_nested_parameters_and_closes_every_cancelled_birth(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../../../../../🌊️flow/🖥️host/📥️evaluation-source/🧫️fixtures/🔣️.json")).unwrap();
 for row in fixture["cases"].as_array().unwrap(){for expected in row["expectedClusters"].as_object().unwrap().values(){for copy in [1,3,64]{for cancel_at in [None,Some(0),Some(9),Some(37),Some(101)]{
  let(mut sources,born,free)=observe(||Sources{source:serde_json::from_value(expected.clone()).unwrap(),result:None});let original=born-free;let source=sources.source.neurons.as_ptr();let(mut cursor,born,free)=observe(BudgetedTreeCopy::new);assert_eq!((born,free),(0,0));let mut births=0;let mut releases=0;let mut idle=0;
  for turn in 0..1000000{if cancel_at==Some(turn){break}let demand=cursor.next_demands(&sources.source,copy).unwrap();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:copy,maximum_capacity_bytes:demand.capacity_bytes,maximum_release_bytes:demand.release_bytes,maximum_depth:demand.depth};for _ in 0..2{let(result,born,free)=observe(||cursor.step(&sources.source,RetainedCloneGrant{maximum_items:0,..grant}).unwrap());assert!(result.is_none());assert_eq!(cursor.step_progress(),Default::default());assert_eq!((born,free),(0,0));}let(result,born,free)=observe(||cursor.step(&sources.source,grant).unwrap());let progress=cursor.step_progress();assert!(progress.fits(grant));assert_eq!((born,free),(progress.retained_capacity_bytes,progress.released_bytes));births+=born;releases+=free;assert_eq!(sources.source.neurons.as_ptr(),source);if let Some(tree)=result{sources.result=Some(tree);break}if progress==RetainedCloneProgress::default(){idle+=1}else{idle=0}assert!(idle<64,"original nested projection stalled phase={} demand={demand:?}",cursor.phase);}
  if cancel_at.is_none(){assert_eq!(sources.result.as_ref().unwrap(),&sources.source);let original=sources.source.neurons[0].params.entry_at_rank(0).unwrap().1 as *const crate::Value;let projected=sources.result.as_ref().unwrap().neurons[0].params.entry_at_rank(0).unwrap().1 as *const crate::Value;assert_eq!(original,projected);}
  let(_,born,free)=observe(||cursor.begin_close());assert_eq!((born,free),(0,0));idle=0;for turn in 0..1000000{if cursor.terminal_is_empty(){break}let demand=cursor.next_close_demands(copy).unwrap();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:copy,maximum_capacity_bytes:demand.capacity_bytes,maximum_release_bytes:demand.release_bytes,maximum_depth:demand.depth};let(step,born,free)=observe(||cursor.close_step(grant).unwrap());assert!(step.progress().fits(grant));assert_eq!((born,free),(step.progress().retained_capacity_bytes,step.progress().released_bytes));births+=born;releases+=free;if step.progress()==RetainedCloneProgress::default(){idle+=1}else{idle=0}assert!(idle<64,"original projection close stalled turn={turn} demand={demand:?}");}assert!(cursor.terminal_is_empty());let(_,born,free)=observe(||drop(cursor));assert_eq!((born,free),(0,0));
  let(mut owner,born,free)=observe(||ControlledRetirement::new(sources).unwrap_or_else(|_|unreachable!()));assert_eq!((born,free),(0,0));for _ in 0..1000000{if owner.terminal_is_empty(){break}let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:copy,maximum_capacity_bytes:owner.next_capacity_byte_demand(copy).unwrap(),maximum_release_bytes:owner.next_release_byte_demand().unwrap(),maximum_depth:owner.next_depth_demand().unwrap()};let(step,born,free)=observe(||owner.step(grant).unwrap());assert!(step.progress().fits(grant));assert_eq!((born,free),(step.progress().retained_capacity_bytes,step.progress().released_bytes));births+=born;releases+=free;}assert!(owner.terminal_is_empty());assert_eq!(original+births,releases);let(_,born,free)=observe(||drop(owner));assert_eq!((born,free),(0,0));eprintln!("[DEBUG] Original nested source copy={copy} cancel={cancel_at:?} original={original} born={births} release={releases} terminalDrop=0");
 }}}}
}
